package netdiag

import (
	"strings"

	"charm.land/lipgloss/v2"
	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/ui/theme"
)

const (
	pickerTitle       = "Trace from"
	pickerEllipsis    = "…"
	pickerCurrentMark = " (current)"
	pickerImageSep    = " · "
	pickerMinBox      = 20
	pickerMaxBox      = 60
	pickerSideMargin  = 4 // cells of the terminal left around the box
	pickerFrameRows   = 2 // top and bottom borders
)

// pathSourcePicker is the "Trace from" selector: a value type with no I/O.
// Every method returns a new value; the table stays the body (Rule 139) and
// the caller draws these lines over it. Loading and notes belong to the footer
// (Rule 128), so they never appear in render.
type pathSourcePicker struct {
	sources []pathSource // this machine first
	current string       // ID of the source in use ("" = this machine)
	cursor  int
	top     int
	loading bool
	note    string
}

// newPathSourcePicker returns a picker offering only this machine, still
// waiting for the container list.
func newPathSourcePicker(current pathSource) pathSourcePicker {
	return pathSourcePicker{
		sources: []pathSource{hostSource()},
		current: current.ID,
		loading: true,
	}
}

// withList returns the picker with the containers of l after this machine. The
// cursor lands on the current source, or on this machine when it is gone.
func (p pathSourcePicker) withList(l pathSourceList) pathSourcePicker {
	p.sources = append([]pathSource{hostSource()}, l.Containers...)
	p.cursor = 0
	for i, s := range p.sources {
		if s.ID == p.current {
			p.cursor = i
			break
		}
	}
	p.top = 0
	p.loading = false
	p.note = l.Note
	return p
}

// move applies a navigation key with rows visible lines and returns the new
// picker. Keys that are not navigation leave it unchanged.
func (p pathSourcePicker) move(key string, rows int) pathSourcePicker {
	rows = max(rows, 1)
	last := len(p.sources) - 1
	switch key {
	case "up":
		p.cursor--
	case "down":
		p.cursor++
	case "pgup":
		p.cursor -= rows
	case "pgdown":
		p.cursor += rows
	case "home":
		p.cursor = 0
	case "end":
		p.cursor = last
	default:
		return p
	}
	p.cursor = min(max(p.cursor, 0), max(last, 0))
	p.top = p.window(rows)
	return p
}

// window returns the first visible index for rows lines, keeping the cursor in
// view while moving as little as possible. top is also capped so a window that
// grew never leaves blank room below the last entry.
func (p pathSourcePicker) window(rows int) int {
	top := min(p.top, p.cursor)
	if p.cursor >= top+rows {
		top = p.cursor - rows + 1
	}
	return max(min(top, len(p.sources)-rows), 0)
}

// selected returns the source under the cursor.
func (p pathSourcePicker) selected() pathSource {
	if p.cursor < 0 || p.cursor >= len(p.sources) {
		return hostSource()
	}
	return p.sources[p.cursor]
}

// render returns the framed selector, one string per line, each exactly
// pickerBoxWidth(width) cells wide. height is the room available, borders
// included.
func (p pathSourcePicker) render(width, height int) []string {
	box := pickerBoxWidth(width)
	inner := box - 2
	rows := min(len(p.sources), max(height-pickerFrameRows, 1))
	top := p.window(rows)

	border := lipgloss.NewStyle().Foreground(theme.ColorPaletteBorder).Background(theme.ColorBackground)
	lines := make([]string, 0, rows+pickerFrameRows)
	lines = append(lines, pickerTopBorder(inner, border))
	for i := top; i < top+rows && i < len(p.sources); i++ {
		lines = append(lines, border.Render("│")+p.renderRow(i, inner)+border.Render("│"))
	}
	return append(lines, border.Render("└"+strings.Repeat("─", inner)+"┘"))
}

// pickerTopBorder draws ┌─ Trace from ───┐ in inner+2 cells.
func pickerTopBorder(inner int, border lipgloss.Style) string {
	dashes := max(inner-ansi.StringWidth(pickerTitle)-3, 0)
	return border.Render("┌─ " + pickerTitle + " " + strings.Repeat("─", dashes) + "┐")
}

// renderRow draws one entry padded to inner cells; the cursor row carries the
// focus mark and the highlight colour.
func (p pathSourcePicker) renderRow(i, inner int) string {
	s := p.sources[i]
	prefix, color := "  ", theme.ColorText
	if i == p.cursor {
		prefix, color = theme.IconCircleSmall+" ", theme.ColorHighlight
	}
	text := prefix + s.label()
	if s.ID == p.current {
		text += pickerCurrentMark
	}
	if !s.isHost() && s.Image != "" {
		text += pickerImageSep + s.Image
	}
	text = ansi.Truncate(text, inner, pickerEllipsis)
	text += strings.Repeat(" ", max(inner-ansi.StringWidth(text), 0))
	return lipgloss.NewStyle().Foreground(color).Background(theme.ColorBackground).Render(text)
}

// pickerBoxWidth is the frame width: the terminal width minus a margin, kept
// between pickerMinBox and pickerMaxBox.
func pickerBoxWidth(width int) int {
	return min(max(width-pickerSideMargin, pickerMinBox), pickerMaxBox)
}

	// two footers that show the shared activity dot, whichever tab is on screen
	// so a tab never comes back with a frozen phase.
	case jobs.FrameMsg:
		m.portsModel.table.SetBlinkPhase(msg.Blink)
		m.footer.SetBlinkPhase(msg.Blink)
		m.interfacesModel.footer.SetBlinkPhase(msg.Blink)
		m.pathModel.footer.SetBlinkPhase(msg.Blink)
		return m, nil

	case stageDoneMsg:
		return m.handleStageDone(msg)

	// Ports sub-model messages.
	case portsTickMsg, portsDataMsg, portsKillResultMsg:
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd

	// The terminal focus reaches the ports poll on every tab: its tick runs
	// whichever tab shows.
	case shared.TerminalFocusMsg:
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd

	// Two tabs now ask before they act — Ports before a kill (§3.26), Forward
	// before dropping the connections a redirection is carrying — so the answer
	// goes to the tab that asked rather than to Ports unconditionally, which
	// would have confirmed a kill from the Forward tab's modal.
	case components.ConfirmModalYesMsg, components.ConfirmModalNoMsg:
		return m.routeConfirm(msg)

	// Forward sub-model messages. ChangedMsg is the router's broadcast, and it
	// reaches this view wherever it stands, on screen or not.
	case forward.ChangedMsg, forwardTickMsg, ForwardFormSubmitMsg, ForwardFormCancelMsg:
		var cmd tea.Cmd
		m.forwardModel, cmd = m.forwardModel.update(msg)
		return m, cmd

	// Path sub-model messages: a trace goes on, and its hops keep arriving,
	// whichever tab is on screen.
	case pathResolvedMsg, pathHopMsg, pathDoneMsg, pathSourcesMsg:
		var cmd tea.Cmd
		m.pathModel, cmd = m.pathModel.update(msg)
		return m, cmd

	// Topology sub-model messages
	case ifaceDataMsg:
		var cmd tea.Cmd
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
		return m, cmd

	case tea.KeyPressMsg:
		return m.handleKey(msg)

	case tea.PasteMsg:
		return m.handlePaste(msg)
	}

	// Each tab holds its own footer, so an expiry has to be offered to all
	// five: the timer fires wherever the user has since navigated. The Path tab
	// also takes the cursor blink of its field.
	m.footer.Handle(msg)
	m.portsModel.footer.Handle(msg)
	m.interfacesModel.footer.Handle(msg)
	m.forwardModel.footer.Handle(msg)
	var cmd tea.Cmd
	m.pathModel, cmd = m.pathModel.update(msg)
	return m, cmd
}

// routeConfirm hands a confirmation answer to the tab that put the modal up.
func (m *Model) routeConfirm(msg tea.Msg) (*Model, tea.Cmd) {
	var cmd tea.Cmd
	if m.activeTab == tabForward {
		m.forwardModel, cmd = m.forwardModel.update(msg)
		return m, cmd
	}
	m.portsModel, cmd = m.portsModel.update(msg)
	return m, cmd
}

// handleStageDone records one stage's answers and starts the next.
func (m *Model) handleStageDone(msg stageDoneMsg) (*Model, tea.Cmd) {
	if msg.gen != m.runGen {
		return m, nil // a superseded run
	}
	m.results = msg.results
	m.rebuildChecksTable()

	steps := netcheck.Steps()
	if msg.next >= len(steps) {
		m.state = StateResults
		m.verdict = netcheck.Summarize(m.results.All())
		log.Printf("INFO [netdiag] run finished: verdict=%s over %d checks",
			m.verdict, len(m.results.All()))
		return m, nil
	}

	m.runStep = msg.next
	m.runStage = steps[msg.next]

	tg, err := m.buildTarget()
	if err != nil {
		// The form has not changed since the run started, so this cannot
		// normally fail. Reporting it beats continuing with a target nobody
		// can name.
		log.Printf("ERROR [netdiag] target became invalid mid-run: %v", err)
		m.state = StateResults
		return m, m.footer.Error("Run stopped — the target is no longer valid")
	}
	return m, runStageCmd(m.runGen, tg, m.checkSettings(), msg.next, m.results)
}

// handlePaste gives pasted text to the field that has the keyboard on the tab on
// screen. It never reaches the key handlers, so no action fires (Rule 111).
func (m *Model) handlePaste(msg tea.PasteMsg) (*Model, tea.Cmd) {
	var cmd tea.Cmd
	switch m.activeTab {
	case tabPorts:
		m.portsModel, cmd = m.portsModel.update(msg)
	case tabInterfaces:
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
	case tabForward:
		m.forwardModel, cmd = m.forwardModel.update(msg)
	case tabPath:
		m.pathModel, cmd = m.pathModel.update(msg)
	default:
		switch {
		case m.filterBar.InEditMode():
			m.filterBar, cmd = m.filterBar.Update(msg)
			m.rebuildChecksTable()
		case m.state == StateInput:
			return m.updateActiveInput(msg)
		}
	}
	return m, cmd
}

func (m *Model) handleKey(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	// A filter bar in edit mode claims every key before anything else, or a
	// query cannot contain the letters the view binds.
	if m.activeTab == tabDiagnostics && m.filterBar.InEditMode() {
		var cmd tea.Cmd
		m.filterBar, cmd = m.filterBar.Update(msg)
		m.rebuildChecksTable()
		return m, cmd
	}

	// An open selector holds every key, tab included: it is a mode.
	if m.activeTab == tabPath && m.pathModel.pickerOpen() {
		var cmd tea.Cmd
		m.pathModel, cmd = m.pathModel.update(msg)
		return m, cmd
	}

	// Tab / Shift+Tab cycles between the tabs (Rule 135)
	switch msg.String() {
	case "tab":
		m.activeTab = (m.activeTab + 1) % tabCount
		return m, nil
	case "shift+tab":
		m.activeTab = (m.activeTab + tabCount - 1) % tabCount
		return m, nil
	}

	// Route to active tab
	if m.activeTab == tabPorts {
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd
	}
	if m.activeTab == tabInterfaces {
		var cmd tea.Cmd
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
		return m, cmd
	}
	if m.activeTab == tabForward {
		var cmd tea.Cmd
		m.forwardModel, cmd = m.forwardModel.update(msg)
		return m, cmd
	}
	if m.activeTab == tabPath {
		var cmd tea.Cmd
		m.pathModel, cmd = m.pathModel.update(msg)
		return m, cmd
	}

	switch m.state {
	case StateInput:
		return m.handleKeyInput(msg)
	case StateRunning:
		return m.handleKeyRunning(msg)
	case StateResults:
		return m.handleKeyResults(msg)
	case StateDetails:
		return m.handleKeyDetails(msg)
	}
	return m, nil
}

