21	// DEVDESK-330 step 6: the selector and the container source wired into the
22	// Path tab. The engine is always the fake: nothing here reads a real engine.
23	
24	const (
25		loadingText = "Reading running containers..."
26		runningWarn = "A path trace is running — esc cancels it"
27	)
28	
29	var webSource = pathSource{ID: idWeb, Name: "web-1", Image: "nginx"}
30	
31	// runningFake offers api and web-1 (running) and db (paused).
32	func runningFake() *fakeEngine {
33		return &fakeEngine{psRows: []docker.Container{
34			{ID: idWeb, Name: "web-1", Image: "nginx", State: "running"},
35			{ID: idAPI, Name: "api", Image: "app", State: "running"},
36			{ID: idDB, Name: "db", Image: "postgres", State: "paused"},
37		}}
38	}
39	
40	// appNetworking is web-1 on one network, app_net.
41	func appNetworking() docker.ContainerNetworking {
42		return docker.ContainerNetworking{
43			Name: "web-1", Running: true, Mode: "app_net",
44			Networks: []docker.EndpointNetwork{{
45				Name:    "app_net",
46				IPv4:    netip.MustParseAddr("172.18.0.5"),
47				Gateway: netip.MustParseAddr("172.18.0.1"),
48			}},
49		}
50	}
51	
52	func pmWith(t *testing.T, f *fakeEngine) *PathModel {
53		t.Helper()
54		pm := newPathModel(f.engine())
55		pm.resize(120, 30)
56		return pm
57	}
58	
59	// pressedSourceKey presses ctrl+o and returns the model, the Cmd and the
60	// message the Cmd answers with.
61	func pressedSourceKey(t *testing.T, pm *PathModel) (*PathModel, tea.Msg) {
62		t.Helper()
63		pm, cmd := pmFeed(t, pm, testutil.Key("ctrl+o"))
64		return pm, testutil.Msg(cmd)
65	}
66	
67	// openedPicker presses ctrl+o and delivers the answer of the listing.
68	func openedPicker(t *testing.T, pm *PathModel) *PathModel {
69		t.Helper()
70		pm, msg := pressedSourceKey(t, pm)
71		if _, ok := msg.(pathSourcesMsg); !ok {
72			t.Fatalf("ctrl+o produced %T, want a pathSourcesMsg from the listing Cmd", msg)
73		}
74		pm, _ = pmFeed(t, pm, msg)
75		return pm
76	}
77	
78	// chosen opens the selector, moves down n entries (0 is this machine) and
79	// presses enter.
80	func chosen(t *testing.T, pm *PathModel, n int) *PathModel {
81		t.Helper()
82		pm = openedPicker(t, pm)
83		for range n {
84			pm, _ = pmFeed(t, pm, testutil.Key("down"))
85		}
86		pm, _ = pmFeed(t, pm, testutil.Key("enter"))
87		return pm
88	}
89	
90	func rowKinds(pm *PathModel) []string {
91		var out []string
92		for _, s := range pm.table.Items() {
93			out = append(out, s.stepCell())
94		}
95		return out
96	}
97	
98	func rowAddress(pm *PathModel, i int) string {
99		items := pm.table.Items()
100		if i >= len(items) {
101			return "<no row>"
102		}
103		return items[i].addressCell()
104	}
105	
106	// donePM returns a model whose trace of 1.1.1.1 from src is done, with one hop.
107	func donePM(t *testing.T, f *fakeEngine, src pathSource) *PathModel {
108		t.Helper()
109		pm := pmWith(t, f)
110		if !src.isHost() {
111			pm.source = src
112		}
113		pm, _ = launched(t, pm, "1.1.1.1")
114		gen := pm.gen
115		pm, _ = pmFeed(t, pm,
116			pathResolvedMsg{gen: gen, addr: netip.MustParseAddr("1.1.1.1"), route: defaultRouteHop(), source: src, ctr: f.inspectNet},
117			pathHopMsg{gen: gen, hop: hopAt(1)},
118			pathDoneMsg{gen: gen, result: nettrace.Result{Outcome: nettrace.OutcomeReached, Hops: []nettrace.Hop{hopAt(1)}}},
119		)
120		if pm.state != pathDone {
121			t.Fatalf("precondition: state = %v, want pathDone", pm.state)
122		}
123		return pm
124	}
